static void prefix_scope(xui_document_snapshot snapshot, const char* source,
    const char* word, const struct prefix_fixture* fixture)
{
    const char* at = strstr(source, word); xui_doc_position_t position;
    xui_doc_node_info_t node = {0}; int quality; unsigned quotes = 0, notes = 0, paragraph = 0;
    TABLE_CHECK(at && xuiDocumentSourceToPosition(snapshot, (uint64_t)(at-source)+1,
        &position, &quality) == XUI_OK && quality == XUI_DOC_MAP_EXACT);
    node.iSize = sizeof(node);
    TABLE_CHECK(xuiDocumentSnapshotGetNode(snapshot, position.iNodeId, &node) == XUI_OK &&
        node.iKind == XUI_DOC_TEXT);
    for (uint64_t id = node.iParentId; id != XUI_DOCUMENT_ROOT;) {
        TABLE_CHECK(xuiDocumentSnapshotGetNode(snapshot, id, &node) == XUI_OK);
        paragraph += node.iKind == XUI_DOC_PARAGRAPH;
        quotes += node.iKind == XUI_DOC_QUOTE; notes += node.iKind == XUI_DOC_FOOTNOTE;
        TABLE_CHECK(node.iParentId != id); id = node.iParentId;
    }
    printf("SCOPE %s depth=%u word=%s paragraph=%u quotes=%u footnotes=%u\n",
        fixture->name, fixture->depth, word, paragraph, quotes, notes); fflush(stdout);
    TABLE_CHECK(paragraph == 1 && quotes == fixture->quotes && notes == fixture->notes);
}
int main(void)
{
    const char* endings[] = {"\n", "\r\n", "\r"};
    unsigned count = 0, rejected = 0, differences = 0;
    for (unsigned fixture = 0; fixture < sizeof(prefix_fixtures)/sizeof(prefix_fixtures[0]); fixture++)
    for (unsigned eol = 0; eol < 3; eol++) for (unsigned bom = 0; bom < 2; bom++)
    for (unsigned eof = 0; eof < 2; eof++) for (unsigned mode = 0; mode < 2; mode++) {
        const struct prefix_fixture* f = &prefix_fixtures[fixture];
        char *before = delete_ending(f->before, endings[eol], bom), *after = delete_ending(f->after, endings[eol], bom);
        if (eof) { before[strlen(before)-strlen(endings[eol])] = 0; after[strlen(after)-strlen(endings[eol])] = 0; }
        table_allocator allocator = {-1, 0}; xui_document d = table_open(before, &allocator), oracle = table_open(after, NULL);
        xui_document_snapshot old, current, expected, restored; xui_doc_position_t caret = {0};
        xui_document_change_set changes; xui_doc_range_t range; uint64_t bytes, revision; char* raw = NULL;
        boundary_case operation = {before, after, "\n", 2, 2, 2}; int result, exact;
        TABLE_CHECK(xuiDocumentClearHistory(d) == XUI_OK && xuiDocumentAcquireSnapshot(d, &old) == XUI_OK &&
            xuiDocumentMarkSaved(d, old) == XUI_OK && xuiDocumentAcquireSnapshot(oracle, &expected) == XUI_OK);
        prefix_scope(old, before, "abcd", f); prefix_scope(expected, after, "cd", f);
        range = boundary_selection(d, old, before, &operation, 0); revision = xuiDocumentGetRevision(d);
        printf("VALID WIDE PREFIX fixture=%u name=%s depth=%u prefix_bytes=%u eol=%u bom=%u eof=%u command=%u\n",
            fixture, f->name, f->depth, f->prefix_bytes, eol, bom, eof, mode); fflush(stdout);
        result = newline_execute(d, &range, mode, &caret, &changes);
        TABLE_CHECK(xuiDocumentAcquireSnapshot(d, &current) == XUI_OK); count++;
        if (result != XUI_OK) {
            rejected++; printf("REJECTED result=%d\n", result);
            TABLE_CHECK(xuiDocumentGetRevision(d) == revision && !xuiDocumentCanUndo(d) && !xuiDocumentIsDirty(d));
            table_source(current, before); table_equivalent(current, old);
        } else {
            formatted_split_same_semantics(current, XUI_DOCUMENT_ROOT, expected, XUI_DOCUMENT_ROOT);
            boundary_caret(d, current, &caret);
            TABLE_CHECK(xuiDocumentSnapshotCopySource(current, NULL, 0, &bytes) == XUI_OK && bytes < SIZE_MAX);
            raw = malloc((size_t)bytes + 1); TABLE_CHECK(raw);
            TABLE_CHECK(xuiDocumentSnapshotCopySource(current, raw, bytes + 1, &bytes) == XUI_OK);
            raw[bytes] = 0; integration_equivalent(current, raw);
            exact = bytes == strlen(after) && !memcmp(raw, after, (size_t)bytes); differences += !exact;
            if (!exact) { printf("RAW DIFFERENCE actual_hex="); for (uint64_t i = 0; i < bytes; i++) printf("%02x", (unsigned char)raw[i]); puts(""); }
            TABLE_CHECK(xuiDocumentUndo(d, NULL) == XUI_OK && !xuiDocumentCanUndo(d) && !xuiDocumentIsDirty(d) &&
                xuiDocumentAcquireSnapshot(d, &restored) == XUI_OK);
            table_source(restored, before); table_equivalent(restored, old); xuiDocumentSnapshotRelease(restored);
            TABLE_CHECK(xuiDocumentRedo(d, NULL) == XUI_OK && xuiDocumentAcquireSnapshot(d, &restored) == XUI_OK);
            table_source(restored, raw); table_equivalent(restored, current); xuiDocumentSnapshotRelease(restored);
            xuiDocumentChangeSetRelease(changes);
        }
        table_source(old, before); xuiDocumentSnapshotRelease(current); xuiDocumentSnapshotRelease(old);
        xuiDocumentSnapshotRelease(expected); xuiDocumentRelease(oracle); xuiDocumentRelease(d); TABLE_CHECK(!allocator.live);
        free(raw); free(before); free(after);
    }
    TABLE_CHECK(count == 528);
    printf("Wide container prefix newline: %u valid scenarios, %u rejections, %u raw differences; independent scope/semantics/reparse/atomicity/history/zero leaks checked\n",
        count, rejected, differences);
    return rejected || differences ? 1 : 0;
}
